/* ---------------- تصدير/استيراد إعدادات البرنامج كملف واحد ----------------
   قائمة محدودة عمداً: إعدادات "تهيئة/تفضيل" فقط (ألوان، أسعار، تصنيفات، بيانات المركز...)،
   وليس عدادات تشغيلية خاصة بكل جهاز/تركيب (أرقام الفواتير التالية، الرقم التسلسلي المالي التالي،
   قفل الفترة المحاسبية، توقيت آخر نسخة احتياطية) لأن نقل هذه القيم لجهاز آخر قد يسبب تعارضاً
   أو تكراراً في الترقيم بدل مجرد نقل "تفضيل". */
/* ---------------- قفل الشاشة بـ PIN (محلي على هذا الجهاز فقط) ---------------- */
let isScreenLocked = false;
let lastActivityAt = Date.now();
function noteActivity(){ lastActivityAt = Date.now(); }
['mousemove','mousedown','keydown','touchstart','scroll'].forEach(evt=>{
  document.addEventListener(evt, noteActivity, {passive:true});
});
function lockScreenNow(){
  if(!settings.pinLock || !settings.pinLock.enabled || !settings.pinLock.pin || String(settings.pinLock.pin).length!==4) return;
  isScreenLocked = true;
  const scr = $('#pin-lock-screen');
  if(scr){
    scr.style.display = 'flex';
    const inp = $('#pin-unlock-input');
    if(inp){ inp.value=''; setTimeout(()=>inp.focus(), 50); }
    const err = $('#pin-unlock-error'); if(err) err.style.display = 'none';
  }
}
function unlockScreenAttempt(){
  const inp = $('#pin-unlock-input');
  const err = $('#pin-unlock-error');
  if(!inp) return;
  if(String(inp.value)===String(settings.pinLock.pin) && inp.value.length===4){
    isScreenLocked = false;
    $('#pin-lock-screen').style.display = 'none';
    noteActivity();
  }else{
    if(err) err.style.display = 'block';
    inp.value = '';
    inp.focus();
  }
}
if($('#btn-pin-unlock-submit')) $('#btn-pin-unlock-submit').addEventListener('click', unlockScreenAttempt);
if($('#pin-unlock-input')) $('#pin-unlock-input').addEventListener('keydown', e=>{ if(e.key==='Enter') unlockScreenAttempt(); });
setInterval(()=>{
  if(isScreenLocked) return;
  if(!settings || !settings.pinLock || !settings.pinLock.enabled || !settings.pinLock.pin) return;
  const minutes = num(settings.pinLock.autoLockMinutes) || 5;
  if(Date.now() - lastActivityAt >= minutes*60000) lockScreenNow();
}, 20000);
function renderPinLockPanel(){
  const pl = settings.pinLock || DEFAULT_SETTINGS.pinLock;
  if($('#pin-enabled-select')) $('#pin-enabled-select').value = pl.enabled ? '1' : '0';
  if($('#pin-code-input')) $('#pin-code-input').value = pl.pin || '';
  if($('#pin-autolock-minutes')) $('#pin-autolock-minutes').value = pl.autoLockMinutes || 5;
}
if($('#btn-save-pin-lock')) $('#btn-save-pin-lock').addEventListener('click', async ()=>{
  const enabled = $('#pin-enabled-select').value === '1';
  const pin = ($('#pin-code-input').value || '').trim();
  const minutes = Math.max(1, Math.min(120, num($('#pin-autolock-minutes').value) || 5));
  if(enabled && !/^\d{4}$/.test(pin)){ showToast('رقم PIN لازم يكون 4 أرقام بالضبط'); return; }
  settings.pinLock = { enabled, pin, autoLockMinutes: minutes };
  await saveSettings();
  await logAudit('edit','الإعدادات', enabled ? `تم تفعيل قفل الشاشة بـ PIN (بعد ${minutes} دقيقة خمول)` : 'تم تعطيل قفل الشاشة بـ PIN');
  noteActivity();
  showToast('تم حفظ إعدادات القفل');
});
if($('#btn-lock-now')) $('#btn-lock-now').addEventListener('click', ()=>{
  if(!settings.pinLock || !settings.pinLock.enabled || !/^\d{4}$/.test(String(settings.pinLock.pin||''))){
    showToast('فعّل القفل وحدّد رقم PIN صحيح (4 أرقام) أولاً ثم احفظ');
    return;
  }
  lockScreenNow();
});
const SETTINGS_EXPORT_KEYS = [
  'courses','nationalities','channels','bagPrice','priceSaudi','priceNonSaudi','expenseCategories',
  'centerInfo','darkMode','soundEnabled','autoBackupEnabled','autoBackupIntervalDays','lowBalanceThreshold',
  'bagOverdueDays','monthlyReportWhatsapp','monthlyPdfReportsWhatsappNumbers','vatPdfReportWhatsappNumbers',
  'reportEmailTo','reportEmailCC',
  'bagFinanceLinkEnabled','powerAutomate'
];
function exportSettingsToFile(){
  const exportObj = {};
  SETTINGS_EXPORT_KEYS.forEach(k=>{ exportObj[k] = settings[k]; });
  const payload = { type:'ftc2-settings-export', exportedAt: new Date().toISOString(), data: exportObj };
  const blob = new Blob([JSON.stringify(payload, null, 2)], {type:'application/json;charset=utf-8;'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `اعدادات_البرنامج_${todayISO()}.json`;
  a.click();
}
async function importSettingsFromFile(file){
  let parsed;
  try{
    const text = await file.text();
    parsed = JSON.parse(text);
  }catch(e){ showToast('تعذّر قراءة الملف — تأكد أنه ملف تصدير إعدادات صحيح'); return; }
  const data = (parsed && parsed.type==='ftc2-settings-export' && parsed.data) ? parsed.data : parsed;
  if(!data || typeof data !== 'object'){ showToast('صيغة الملف غير صحيحة'); return; }
  const foundKeys = SETTINGS_EXPORT_KEYS.filter(k=> Object.prototype.hasOwnProperty.call(data, k));
  if(!foundKeys.length){ showToast('لم يتم التعرّف على أي إعدادات صالحة داخل هذا الملف'); return; }
  if(!await customConfirm(`سيتم استيراد ${foundKeys.length} إعداد من الملف (الألوان، الأسعار، طرق الدفع، بيانات المركز...) وسيحل محل الإعدادات الحالية المطابقة. متابعة؟`)) return;
  snapshotState('استيراد إعدادات البرنامج من ملف');
  foundKeys.forEach(k=>{ settings[k] = data[k]; });
  await saveSettings();
  applyTheme(!!settings.darkMode);
  await logAudit('edit','الإعدادات', `تم استيراد إعدادات البرنامج من ملف خارجي (${foundKeys.length} إعداد)`);
  renderSettings();
  showToast('تم استيراد الإعدادات بنجاح');
}
if($('#btn-export-settings')) $('#btn-export-settings').addEventListener('click', exportSettingsToFile);
if($('#btn-import-settings')) $('#btn-import-settings').addEventListener('click', ()=> $('#import-settings-input').click());
if($('#import-settings-input')) $('#import-settings-input').addEventListener('change', async e=>{
  const file = e.target.files[0];
  e.target.value = '';
  if(file) await importSettingsFromFile(file);
});
function renderServerSyncPanel(){
  const label = $('#server-sync-status-label');
  const btn = $('#btn-toggle-server-sync');
  if(!label || !btn) return;
  if(manualOfflineMode){
    label.textContent = '🔒 متوقف — يعمل من الجهاز فقط حالياً';
    label.style.color = 'var(--red)';
    btn.textContent = '🔌 إعادة تفعيل الاتصال ورفع التعديلات';
    btn.className = 'btn btn-primary btn-sm';
  }else{
    label.textContent = '🟢 متصل بالسيرفر (تلقائي)';
    label.style.color = 'var(--teal)';
    btn.textContent = '⏸️ إيقاف الاتصال والعمل من الجهاز فقط';
    btn.className = 'btn btn-danger btn-sm';
  }
}
if($('#btn-toggle-server-sync')) $('#btn-toggle-server-sync').addEventListener('click', async ()=>{
  if(!manualOfflineMode){
    if(!await customConfirm('سيتوقف البرنامج عن الاتصال بالسيرفر تماماً، وسيعمل فقط بالنسخة المحفوظة على هذا الجهاز. أي تعديل تسويه سيُحفظ محلياً بدون رفعه للسيرفر حتى تُعيد تفعيل الاتصال يدوياً. متابعة؟')) return;
    setManualOfflineMode(true);
    showToast('تم إيقاف الاتصال — البرنامج يعمل الآن من نسخة الجهاز فقط');
  }else{
    setManualOfflineMode(false);
    showToast('تمت إعادة تفعيل الاتصال — جارٍ رفع أي تعديلات محفوظة محلياً تلقائياً');
  }
  renderServerSyncPanel();
});
/* كثافة صفوف الجداول (مريح/مضغوط) — تفضيل عرض شخصي بحت، فيُحفَظ محلياً في هذا
   المتصفح فقط (localStorage) وليس ضمن إعدادات الحساب المشتركة بين المستخدمين،
   حتى لا يفرض تفضيل شخص واحد نفس الكثافة على بقية الفريق. */
function applyRowDensity(isCompact){
  document.body.classList.toggle('density-compact', !!isCompact);
  const btn = $('#btn-density-toggle');
  if(btn) btn.classList.toggle('active', !!isCompact);
}
try{ applyRowDensity(localStorage.getItem('ftc2-row-density')==='compact'); }catch(e){}
$('#btn-density-toggle')?.addEventListener('click', ()=>{
  const next = !document.body.classList.contains('density-compact');
  applyRowDensity(next);
  try{ localStorage.setItem('ftc2-row-density', next ? 'compact' : 'comfortable'); }catch(e){}
});
/* طي/توسيع القائمة الجانبية (عرض الأيقونات فقط بدون النصوص) — تفضيل شخصي يُحفظ محلياً
   في هذا المتصفح فقط، ويضيف عنوان (title) لكل زر عند الطي حتى يبقى واضحاً عند تمرير الفأرة فوقه. */
function applySidebarCollapsed(isCollapsed){
  const nav = $('nav.tabs');
  if(!nav) return;
  nav.classList.toggle('collapsed', !!isCollapsed);
  if(isCollapsed){
    nav.querySelectorAll(':scope > button, .nav-flyout-row > button').forEach(btn=>{
      if(!btn.title){
        const label = btn.querySelector('span')?.textContent?.trim();
        if(label) btn.title = label;
      }
    });
  }
}
try{ applySidebarCollapsed(localStorage.getItem('ftc2-sidebar-collapsed')==='1'); }catch(e){}
$('#btn-sidebar-collapse')?.addEventListener('click', ()=>{
  const next = !$('nav.tabs')?.classList.contains('collapsed');
  applySidebarCollapsed(next);
  try{ localStorage.setItem('ftc2-sidebar-collapsed', next ? '1' : '0'); }catch(e){}
});

/* ============ قائمة المستخدم المنسدلة بجانب الاسم (الإعدادات / تحديث الشيت / اللغة /
   كتم الصوت / الوضع الليلي-النهاري / كثافة الصفوف / اختصارات لوحة المفاتيح) — تجميع
   الأزرار دي في قائمة واحدة بدل ما تكون منتشرة كأزرار مستقلة في شريط الهيدر العلوي. ============ */
const userMenuWrap = $('#user-menu-wrap');
const userMenuToggleBtn = $('#btn-user-menu-toggle');
const userMenuDropdown = $('#user-menu-dropdown');
// اسم اليوزر نفسه بقى هو زر فتح/قفل القائمة المنسدلة (اتشالت علامة السهم المنفصلة)، وبما إنه
// <span role="button"> مش <button> حقيقي، محتاجين ندعم كمان تفعيله بلوحة المفاتيح (Enter/Space).
userMenuToggleBtn?.addEventListener('keydown', (e)=>{
  if(e.key==='Enter' || e.key===' '){
    e.preventDefault();
    userMenuToggleBtn.click();
  }
});
// header.top فيه backdrop-filter (بجانب overflow:hidden)، و backdrop-filter/filter بيعمل
// containing block جديد لأي عنصر position:fixed بداخله (حسب سبيك الـCSS) — فحتى لو حوّلنا
// القائمة المنسدلة لـ position:fixed، هي بتفضل "محبوسة" جوه حدود الهيدر المقصوصة (overflow:hidden)
// ومش بتظهر فيها أي حاجة فعليًا. الحل الجذري: ننقل عنصر القائمة نفسه (DOM) ليكون ابن مباشر
// لـ body، بعيدًا تمامًا عن أي ancestor عنده backdrop-filter أو overflow:hidden.
if(userMenuDropdown && userMenuDropdown.parentElement !== document.body){
  document.body.appendChild(userMenuDropdown);
}
function closeUserMenuDropdown(){
  userMenuDropdown?.classList.remove('show');
  userMenuWrap?.classList.remove('open');
  userMenuToggleBtn?.setAttribute('aria-expanded','false');
}
userMenuToggleBtn?.addEventListener('click', (e)=>{
  e.stopPropagation();
  const wasOpen = userMenuDropdown?.classList.contains('show');
  closeUserMenuDropdown();
  if(!wasOpen){
    userMenuDropdown.classList.add('show');
    userMenuWrap.classList.add('open');
    userMenuToggleBtn.setAttribute('aria-expanded','true');
    // القائمة بقت ابن مباشر لـ body، فموضعها بـ position:fixed بيتحسب دلوقتي فعليًا بالنسبة
    // للشاشة كلها (زي قائمة "أنواع الدورات" المنسدلة الموجودة أصلاً بجانب زر "العملاء").
    const r = userMenuToggleBtn.getBoundingClientRect();
    userMenuDropdown.style.position = 'fixed';
    userMenuDropdown.style.top = (r.bottom + 8) + 'px';
    userMenuDropdown.style.right = (window.innerWidth - r.right) + 'px';
    userMenuDropdown.style.left = 'auto';
  }
});
// إغلاق القائمة بعد اختيار أي عنصر (تحديث الشيت/اللغة/الثيم/الكثافة) — عدا كتم الصوت اللي
// المستخدم ممكن يحب يجرّبه أكتر من مرة متتالية، فبنسيبها مفتوحة له فقط.
userMenuDropdown?.addEventListener('click', (e)=>{
  const btn = e.target.closest('button');
  if(btn && btn.id!=='btn-sound-toggle') closeUserMenuDropdown();
});
document.addEventListener('click', (e)=>{
  if(userMenuDropdown?.classList.contains('show') && !userMenuWrap.contains(e.target)) closeUserMenuDropdown();
});
